CREATE TABLE `pengajuan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `jenis_surat` varchar(100) NOT NULL,
  `nomor_surat_generated` varchar(150) DEFAULT NULL,
  `nomor_urut` int(11) DEFAULT NULL,
  `data_form` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`data_form`)),
  `status` enum('menunggu','menunggu_ptsp','menunggu_kasi','menunggu_sekcam','menunggu_camat','disetujui','ditolak') DEFAULT 'menunggu_ptsp',
  `is_ttd_dibubuhkan` tinyint(1) DEFAULT 0,
  `ttd_id` int(11) DEFAULT NULL,
  `waktu_ttd_dibubuhkan` timestamp NULL DEFAULT NULL,
  `ttd_dibubuhkan_oleh` varchar(150) DEFAULT NULL,
  `kasi_tujuan` varchar(50) DEFAULT NULL,
  `ptsp_oleh` varchar(150) DEFAULT NULL,
  `waktu_validasi_ptsp` timestamp NULL DEFAULT NULL,
  `catatan_ptsp` text DEFAULT NULL,
  `paraf_kasi_oleh` varchar(150) DEFAULT NULL,
  `paraf_kasi_nip` varchar(50) DEFAULT NULL,
  `paraf_kasi_jabatan` varchar(150) DEFAULT NULL,
  `waktu_paraf_kasi` timestamp NULL DEFAULT NULL,
  `catatan_kasi` text DEFAULT NULL,
  `redaksi_kasi_pembuka` text DEFAULT NULL,
  `redaksi_kasi_penutup` text DEFAULT NULL,
  `paraf_sekcam_oleh` varchar(150) DEFAULT NULL,
  `paraf_sekcam_nip` varchar(50) DEFAULT NULL,
  `waktu_paraf_sekcam` timestamp NULL DEFAULT NULL,
  `catatan_sekcam` text DEFAULT NULL,
  `tte_camat_oleh` varchar(150) DEFAULT NULL,
  `tte_camat_nip` varchar(50) DEFAULT NULL,
  `tte_kode` varchar(100) DEFAULT NULL,
  `catatan_tolak` text DEFAULT NULL,
  `ditolak_oleh` varchar(150) DEFAULT NULL,
  `is_revisi` tinyint(1) DEFAULT 0,
  `waktu_revisi` timestamp NULL DEFAULT NULL,
  `waktu_pengajuan` timestamp NOT NULL DEFAULT current_timestamp(),
  `waktu_verifikasi` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `pengajuan_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
