INSERT INTO `tanda_tangan` (`id`, `judul_ttd`, `tipe_ttd`, `teks_atas`, `jabatan`, `nama_pejabat`, `pangkat_golongan`, `nip`, `gambar_ttd`, `is_default`, `created_at`, `updated_at`) VALUES (1,'Tanda Tangan Elektronik Camat Cisayong (Utama)','elektronik_kotak','Ditandatangani secara elektronik oleh','CAMAT CISAYONG','AYI MULYANA HERNIWAN, SE., M.Si.','Pembina : Tk. I IV/b','19721003 199403 1 012',NULL,0,'2026-11-11 05:34:59','2026-11-11 21:01:53'),(2,'Tanda Tangan Elektronik a.n. Camat (Sekretaris Camat)','elektronik_kotak','Ditandatangani secara elektronik a.n. Camat Cisayong','SEKRETARIS CAMAT CISAYONG','Drs. H. UNDANG SUHENDAR, M.Si.','Pembina Tk. I - IV/b','19750610 199603 1 003',NULL,0,'2026-11-11 05:34:59','2026-11-11 05:34:59'),(3,'Tanda Tangan Manual & Stempel Kecamatan','gambar_upload','Ditandatangani & Distempel Resmi','CAMAT CISAYONG','AYI MULYANA HERNIWAN, SE., M.Si.','Pembina : Tk. I IV/b','19721003 199403 1 012',NULL,0,'2026-11-11 05:34:59','2026-11-13 20:42:24'),(4,'Tanda Tangan Elektronik Camat Cisayong','elektronik_kotak','Ditandatangani secara elektronik oleh','CAMAT CISAYONG','AYI MULYANA HERNIWAN, SE., M.Si.','Pembina Tk. I IV/b','19720315 199803 1 004','',0,'2026-11-11 20:50:27','2026-11-11 20:50:27'),(6,'Tanda Tangan Elektronik Camat Cisayong','gambar_upload','Ditandatangani secara elektronik oleh','CAMAT CISAYONG','AYI MULYANA HERNIWAN, SE., M.Si.','Pembina Tk. I IV/b','19720315 199803 1 004','assets/uploads/ttd/ttd_1794456701_6af53c7d154db.jpeg',1,'2026-11-11 21:11:41','2026-11-13 20:42:24');
DROP TABLE IF EXISTS `templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `jenis_surat` varchar(100) NOT NULL,
  `kategori_pemohon` enum('masyarakat','desa') DEFAULT 'masyarakat',
  `kasi_default` varchar(50) DEFAULT 'kasi_kesra',
  `kode_klasifikasi` varchar(50) NOT NULL,
  `format_nomor` varchar(100) NOT NULL,
  `judul_surat` varchar(255) NOT NULL,
  `sifat` varchar(100) DEFAULT NULL,
  `lampiran` varchar(100) DEFAULT NULL,
  `perihal` varchar(255) DEFAULT NULL,
  `tujuan` varchar(255) DEFAULT NULL,
  `pembuka` text NOT NULL,
  `penutup` text NOT NULL,
  `penandatangan_nama` varchar(150) NOT NULL,
  `penandatangan_nip` varchar(100) NOT NULL,
  `penandatangan_jabatan` varchar(150) NOT NULL,
  `penandatangan_pangkat` varchar(150) NOT NULL,
  `is_tte` tinyint(1) DEFAULT 1,
  `form_fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`form_fields`)),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `jenis_surat` (`jenis_surat`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
INSERT INTO `templates` (`id`, `jenis_surat`, `kategori_pemohon`, `kasi_default`, `kode_klasifikasi`, `format_nomor`, `judul_surat`, `sifat`, `lampiran`, `perihal`, `tujuan`, `pembuka`, `penutup`, `penandatangan_nama`, `penandatangan_nip`, `penandatangan_jabatan`, `penandatangan_pangkat`, `is_tte`, `form_fields`, `updated_at`) VALUES (1,'Dispensasi Nikah','masyarakat','kasi_kesra','400.8','[KODE]/[URUT]/Kec/[TAHUN]','SURAT KETERANGAN DISPENSASI NIKAH','','','','','Sesuai dengan Peraturan Pemerintah Nomor 9 tahun 1975 Bab II Pasal 1, Camat Cisayong Atas Nama Bupati Taikmalaya, dengan ini memberikan Dispensasi Nikah kepada:','Demikian agar menjadi maklum dan untuk digunakan sebagaimana mestinya.','SUTARYO, S.T.','19740817 199803 1 004','Camat Cisayong','Pembina',1,NULL,'2026-06-29 09:16:42'),(2,'Alokasi Dana Daerah (ADD)','desa','kasi_pmd','900.10.2.4','B/[KODE]/[URUT]/Kec.Pum/[TAHUN]','Rekomendasi Pencairan ADD','Penting','1 (satu) berkas','Rekomendasi Pencairan ADD','Bupati Tasikmalaya\r\nMelalui:\r\nKepala DPMD Kab. Tasikmalaya\r\ndi\r\nCIBINONG','Berdasarkan permohonan pencairan ADD Desa terkait perihal Permohonan Pencairan Alokasi Dana Desa (ADD), berdasarkan hasil verifikasi dengan ini kami merekomendasikan permohonan Pencairan Alokasi Dana Desa (ADD) dimaksud.\r\n\r\nAdapun kelengkapan pengajuan pencairan sebagaimana terlampir, meliputi:\r\n1. Surat Permohonan Pencairan;\r\n2. Fakta Integritas;\r\n3. Bukti Pembayaran;\r\n4. Surat Pernyataan Tanggungjawab Mutlak (SPTJM);\r\n5. Foto copy KTP Kepala Desa dan Bendahara Desa;\r\n6. Foto copy Rekening Pemerintahan Desa;\r\n7. Foto Copy NPWP;\r\n8. Lembar Verifikasi Kecamatan;\r\n9. Data Jumlah Kaur, Kasi, Kadus, BPD, RT dan RW.','Demikian untuk maklum, atas terkabulnya kami ucapkan terimakasih.','AYI MULYANA HERNIWAN, SE., M.Si.','19721003 199403 1 012','Camat Cibinong','Pembina : Tk.I IV/b',1,NULL,'2026-11-10 07:43:50'),(3,'Surat Keterangan Usaha','masyarakat','kasi_kesra','500','[KODE]/[URUT]/Kec/[TAHUN]','SURAT KETERANGAN USAHA','','','','','Yang bertanda tangan di bawah ini, Camat Cisayong Sutaryo, S.T., Kecamatan Cisayong, Kabupaten Tasikmalaya, dengan ini menerangkan bahwa:','Demikian Surat Keterangan Usaha ini dibuat dengan sesungguhnya, agar yang berkepentingan mengetahui dan maklum adanya.','AYI MULYANA HERNIWAN, SE., M.Si.','19721003 199403 1 012','CAMAT CISAYONG','Pembina : Tk.I IV/b',1,'[{\"label\":\"Nama\",\"name\":\"nama\",\"type\":\"text\",\"required\":true},{\"label\":\"NIK\",\"name\":\"nik\",\"type\":\"text\",\"required\":true},{\"label\":\"Tempat Tanggal Lahir\",\"name\":\"tempat_tanggal_lahir\",\"type\":\"text\",\"required\":true},{\"label\":\"Jenis Kelamin\",\"name\":\"jenis_kelamin\",\"type\":\"text\",\"required\":true},{\"label\":\"Alamat Tempat Tinggal\",\"name\":\"alamat_tempat_tinggal\",\"type\":\"textarea\",\"required\":true},{\"label\":\"Alamat Usaha\",\"name\":\"alamat_usaha\",\"type\":\"textarea\",\"required\":true},{\"label\":\"Bentuk Perusahaan\",\"name\":\"bentuk_perusahaan\",\"type\":\"text\",\"required\":true},{\"label\":\"Jenis Usaha\",\"name\":\"jenis_usaha\",\"type\":\"text\",\"required\":true},{\"label\":\"Jenis Barang/Jasa\",\"name\":\"jenis_barang___jasa\",\"type\":\"text\",\"required\":true},{\"label\":\"Keadaan Usaha\",\"name\":\"keadaan_usaha\",\"type\":\"text\",\"required\":true}]','2026-06-30 01:59:38'),(4,'Surat Keterangan Tidak Mampu','masyarakat','kasi_kesra','421','[KODE]/[URUT]/Kec/[TAHUN]','SURAT KETERANGAN TIDAK MAMPU','','','','','Yang bertanda tangan di bawah ini Kepala Kecamatan Cisayong Kabupaten Tasikmalay. Menerangkan dengan sebenarnya bahwa :','Orang tersebut adalah penduduk warga kami, dan menurut sepanjang pengetahuan kami benar dari keluarga TIDAK MAMPU serta termasuk golongan anggota rumah tangga miskin (RTM), dan perlu di bantu untuk Persayaratan ...\r\nDemikian agar menjadi maklum dan di pergunakan seperlunya.','AYI MULYANA HERNIWAN, SE., M.Si.','19721003 199403 1 012','CAMAT CISAYONG','Pembina : Tk.I IV/b',1,'[{\"label\":\"Tempat Tanggal Lahir\",\"name\":\"tempat_tanggal_lahir\",\"type\":\"date\",\"required\":true},{\"label\":\"Jenis Kelamin\",\"name\":\"jenis_kelamin\",\"type\":\"text\",\"required\":true},{\"label\":\"Status Perkawinan\",\"name\":\"status_perkawinan\",\"type\":\"text\",\"required\":true},{\"label\":\"Pekerjaan\",\"name\":\"pekerjaan\",\"type\":\"text\",\"required\":true},{\"label\":\"Penghasilan per bulan\",\"name\":\"penghasilan_per_bulan\",\"type\":\"text\",\"required\":true},{\"label\":\"Alamat\",\"name\":\"alamat\",\"type\":\"textarea\",\"required\":true},{\"label\":\"KSKKSK\",\"name\":\"kskksk\",\"type\":\"file\",\"required\":true}]','2026-06-30 19:04:05'),(5,'SKTM (Surat Keterangan Tidak Mampu)','masyarakat','kasi_kesra','460','[KODE]/[URUT]/Kec.Kesra/[TAHUN]','SURAT KETERANGAN TIDAK MAMPU (SKTM)',NULL,NULL,NULL,NULL,'Yang bertanda tangan di bawah ini Camat Cisayong Kabupaten Tasikmalaya, berdasarkan Surat Pengantar dari Pemerintah Desa serta hasil verifikasi berkas yang bersangkutan, dengan ini menerangkan bahwa:','Berdasarkan data dan keterangan dari Pemerintah Desa setempat, nama tersebut di atas adalah benar warga yang tergolong Keluarga Tidak Mampu / Pra-Sejahtera. Surat Keterangan ini diberikan untuk keperluan administrasi yang bersangkutan.\n\nDemikian Surat Keterangan Tidak Mampu ini dibuat dengan sebenarnya untuk dapat dipergunakan sebagaimana mestinya.','AYI MULYANA HERNIWAN, SE., M.Si.','19721003 199403 1 012','CAMAT CISAYONG','Pembina Tk.I - IV/b',1,'[{\"label\":\"Tempat \\/ Tanggal Lahir\",\"name\":\"tempat_tanggal_lahir\",\"type\":\"text\",\"required\":true},{\"label\":\"Jenis Kelamin\",\"name\":\"jenis_kelamin\",\"type\":\"text\",\"required\":true},{\"label\":\"Pekerjaan\",\"name\":\"pekerjaan\",\"type\":\"text\",\"required\":true},{\"label\":\"Penghasilan Rata-rata \\/ Bulan (Rp)\",\"name\":\"penghasilan_per_bulan\",\"type\":\"text\",\"required\":true},{\"label\":\"Jumlah Tanggungan Keluarga\",\"name\":\"jumlah_tanggungan\",\"type\":\"number\",\"required\":true},{\"label\":\"Keperluan Pengajuan SKTM\",\"name\":\"keperluan_sktm\",\"type\":\"text\",\"required\":true},{\"label\":\"Alamat Lengkap Sesuai KTP\",\"name\":\"alamat_lengkap\",\"type\":\"textarea\",\"required\":true},{\"label\":\"KTP Pemohon\",\"name\":\"file_ktp\",\"type\":\"file\",\"required\":true},{\"label\":\"Kartu Keluarga (KK)\",\"name\":\"file_kk\",\"type\":\"file\",\"required\":true},{\"label\":\"Surat Pengantar Desa \\/ RT-RW\",\"name\":\"file_pengantar_desa\",\"type\":\"file\",\"required\":true}]','2026-11-10 07:43:50'),(6,'Surat Keterangan Ahli Waris','masyarakat','kasi_pemerintahan','474.3','[KODE]/[URUT]/Kec.Pem/[TAHUN]','SURAT KETERANGAN AHLI WARIS',NULL,NULL,NULL,NULL,'Kami yang bertanda tangan di bawah ini, Camat Cisayong Kabupaten Tasikmalaya, berdasarkan Surat Pernyataan Ahli Waris yang diketahui oleh Kepala Desa serta hasil pemeriksaan administrasi pemerintahan, dengan ini menerangkan dengan sebenarnya bahwa:','Adalah benar para Ahli Waris yang sah dari Almarhum/Almarhumah tersebut di atas dan tidak ada ahli waris lainnya selain yang telah disebutkan.\n\nDemikian Surat Keterangan Ahli Waris ini dibuat dan disahkan di tingkat Kecamatan untuk dipergunakan sebagaimana mestinya.','AYI MULYANA HERNIWAN, SE., M.Si.','19721003 199403 1 012','CAMAT CISAYONG','Pembina Tk.I - IV/b',1,'[{\"label\":\"Nama Almarhum \\/ Almarhumah (Pewaris)\",\"name\":\"nama_pewaris\",\"type\":\"text\",\"required\":true},{\"label\":\"Tanggal Meninggal Dunia\",\"name\":\"tanggal_meninggal\",\"type\":\"date\",\"required\":true},{\"label\":\"Tempat Meninggal & Nomor Akta\\/Surat Kematian\",\"name\":\"nomor_surat_kematian\",\"type\":\"text\",\"required\":true},{\"label\":\"Alamat Terakhir Pewaris\",\"name\":\"alamat_terakhir_pewaris\",\"type\":\"textarea\",\"required\":true},{\"label\":\"Hubungan Pemohon dengan Pewaris\",\"name\":\"hubungan_waris\",\"type\":\"text\",\"required\":true},{\"label\":\"Daftar Lengkap Nama Ahli Waris & Hubungan Keluarga\",\"name\":\"daftar_ahli_waris\",\"type\":\"textarea\",\"required\":true},{\"label\":\"Keperluan Administrasi Ahli Waris\",\"name\":\"keperluan_waris\",\"type\":\"text\",\"required\":true},{\"label\":\"KTP & KK Para Ahli Waris (PDF\\/JPG)\",\"name\":\"file_ktp_kk_waris\",\"type\":\"file\",\"required\":true},{\"label\":\"Surat Kematian \\/ Akta Kematian Pewaris\",\"name\":\"file_akta_kematian\",\"type\":\"file\",\"required\":true},{\"label\":\"Surat Pernyataan Waris dari Desa\",\"name\":\"file_pernyataan_desa\",\"type\":\"file\",\"required\":true}]','2026-11-10 07:43:50'),(7,'Surat Keterangan Usaha (SKU) / Domisili','masyarakat','kasi_pmd','503','[KODE]/[URUT]/Kec.PMD/[TAHUN]','SURAT KETERANGAN USAHA & DOMISILI',NULL,NULL,NULL,NULL,'Yang bertanda tangan di bawah ini Camat Cisayong Kabupaten Tasikmalaya, berdasarkan Surat Keterangan dari Kepala Desa di lingkungan Kecamatan Cisayong, dengan ini menerangkan bahwa:','Nama tersebut di atas benar memiliki dan menjalankan kegiatan usaha yang berdomisili di wilayah Kecamatan Cisayong Kabupaten Tasikmalaya. Surat keterangan ini berlaku untuk keperluan administrasi perbankan/perizinan usaha mikro.\n\nDemikian Surat Keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.','AYI MULYANA HERNIWAN, SE., M.Si.','19721003 199403 1 012','CAMAT CISAYONG','Pembina Tk.I - IV/b',1,'[{\"label\":\"Tempat \\/ Tanggal Lahir\",\"name\":\"tempat_tanggal_lahir\",\"type\":\"text\",\"required\":true},{\"label\":\"Pekerjaan Pokok\",\"name\":\"pekerjaan\",\"type\":\"text\",\"required\":true},{\"label\":\"Nama Usaha \\/ Toko \\/ UMKM\",\"name\":\"nama_usaha\",\"type\":\"text\",\"required\":true},{\"label\":\"Bidang \\/ Jenis Usaha\",\"name\":\"bidang_usaha\",\"type\":\"text\",\"required\":true},{\"label\":\"Lama Usaha Berjalan\",\"name\":\"lama_usaha\",\"type\":\"text\",\"required\":true},{\"label\":\"Alamat Lengkap Tempat Usaha\",\"name\":\"alamat_usaha\",\"type\":\"textarea\",\"required\":true},{\"label\":\"Keperluan Pengajuan SKU \\/ Domisili\",\"name\":\"keperluan_surat\",\"type\":\"text\",\"required\":true},{\"label\":\"KTP Pemohon\",\"name\":\"file_ktp\",\"type\":\"file\",\"required\":true},{\"label\":\"Kartu Keluarga (KK)\",\"name\":\"file_kk\",\"type\":\"file\",\"required\":true},{\"label\":\"Surat Pengantar SKU Desa & Foto Usaha\",\"name\":\"file_pengantar_sku\",\"type\":\"file\",\"required\":true}]','2026-11-10 07:43:50'),(8,'Surat Rekomendasi Izin Keramaian / Acara','masyarakat','kasi_trantib','300','[KODE]/[URUT]/Kec.Trantib/[TAHUN]','SURAT REKOMENDASI IZIN KERAMAIAN','Biasa','1 (satu) berkas','Rekomendasi Izin Keramaian / Kegiatan Masyarakat','Kapolsek Cisayong\ndi\nCISAYONG','Berdasarkan permohonan rekomendasi izin keramaian dari warga/panitia penyelenggara serta surat pengantar dari Kepala Desa setempat, setelah dilakukan pemeriksaan ketentraman dan ketertiban umum (Trantibum), dengan ini Camat Cisayong memberikan rekomendasi kegiatan kepada:','Dengan ketentuan penanggung jawab wajib menjaga ketertiban umum, keamanan lingkungan, serta mematuhi peraturan perundang-undangan yang berlaku.\n\nDemikian surat rekomendasi ini diberikan untuk bahan proses lebih lanjut.','AYI MULYANA HERNIWAN, SE., M.Si.','19721003 199403 1 012','CAMAT CISAYONG','Pembina Tk.I - IV/b',1,'[{\"label\":\"Nama Kegiatan \\/ Acara\",\"name\":\"nama_acara\",\"type\":\"text\",\"required\":true},{\"label\":\"Jabatan Pemohon dalam Acara\\/Kepanitiaan\",\"name\":\"jabatan_kepanitiaan\",\"type\":\"text\",\"required\":true},{\"label\":\"Tanggal Pelaksanaan Acara\",\"name\":\"tanggal_acara\",\"type\":\"date\",\"required\":true},{\"label\":\"Waktu \\/ Jam Pelaksanaan\",\"name\":\"waktu_acara\",\"type\":\"text\",\"required\":true},{\"label\":\"Estimasi Jumlah Undangan \\/ Peserta (Orang)\",\"name\":\"estimasi_peserta\",\"type\":\"number\",\"required\":true},{\"label\":\"Bentuk Hiburan \\/ Rangkaian Kegiatan\",\"name\":\"bentuk_hiburan\",\"type\":\"text\",\"required\":true},{\"label\":\"Lokasi Lengkap Tempat Acara\",\"name\":\"lokasi_acara\",\"type\":\"textarea\",\"required\":true},{\"label\":\"KTP Penanggung Jawab Acara\",\"name\":\"file_ktp\",\"type\":\"file\",\"required\":true},{\"label\":\"Surat Pengantar Desa\",\"name\":\"file_pengantar_desa\",\"type\":\"file\",\"required\":true},{\"label\":\"Surat Pernyataan Menjaga Ketertiban\",\"name\":\"file_pernyataan_trantib\",\"type\":\"file\",\"required\":true}]','2026-11-10 07:43:50');
DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama` varchar(150) NOT NULL,
  `username` varchar(100) NOT NULL,
  `email` varchar(150) DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `role` enum('masyarakat','desa','ptsp','kasi_pemerintahan','kasi_kesra','kasi_pmd','kasi_trantib','sekcam','camat','admin') NOT NULL,
  `instansi_desa` varchar(150) DEFAULT NULL,
  `jabatan` varchar(150) DEFAULT NULL,
  `nip` varchar(50) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
